import{_ as t,o as r,c as s,a0 as a}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),o={name:"guide/introduction.md"};function n(i,e,d,l,c,p){return r(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>blogger-go</strong> is a complete Go SDK for the <a href="https://developers.google.com/blogger/docs/3.0/getting_started" target="_blank" rel="noreferrer">Blogger API v3</a>.</p><p>It covers all 8 resources and 33 methods from the canonical discovery document (revision 20260924), using proper Go idioms including context propagation, typed errors, request builders, and Google OAuth2 integration.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Complete API coverage</strong> — 8 resources, 33 methods matching the official discovery doc</li><li><strong>Type-safe schemas</strong> — 15 model types derived directly from the API specification</li><li><strong>Builder pattern</strong> — Chainable request construction with option helpers</li><li><strong>Typed errors</strong> — Structured <code>APIError</code> with code, message, and reasons</li><li><strong>Pagination support</strong> — Cursor-based pagination helpers (<code>Token</code>, <code>PaginationResult</code>)</li><li><strong>OAuth2 ready</strong> — Integration with <code>golang.org/x/oauth2</code> for authentication</li><li><strong>Context propagation</strong> — All methods accept <code>context.Context</code> as first parameter</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>blogger-go/</span></span>
<span class="line"><span>├── client.go          # Client entry point with 8 service accessors</span></span>
<span class="line"><span>├── auth.go            # OAuth2 token source helpers</span></span>
<span class="line"><span>├── gen/</span></span>
<span class="line"><span>│   ├── builder/       # Request builder, errors, pagination</span></span>
<span class="line"><span>│   ├── schemas/       # 15 model structs</span></span>
<span class="line"><span>│   └── services/      # 8 service implementations</span></span>
<span class="line"><span>└── internal/          # Internal helpers</span></span></code></pre></div><h2 id="resources-covered" tabindex="-1">Resources Covered <a class="header-anchor" href="#resources-covered" aria-label="Permalink to &quot;Resources Covered&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Methods</th></tr></thead><tbody><tr><td>Blogs</td><td>Get, GetByUrl, ListByUser</td></tr><tr><td>Comments</td><td>Get, List, ListByBlog, Approve, Delete, MarkAsSpam, RemoveContent</td></tr><tr><td>Pages</td><td>Get, List, Insert, Update, Patch, Delete, Publish, Revert</td></tr><tr><td>Posts</td><td>Get, List, Search, GetByPath, Insert, Update, Patch, Delete, Publish, Revert</td></tr><tr><td>Users</td><td>Get</td></tr><tr><td>BlogUserInfos</td><td>Get</td></tr><tr><td>PageViews</td><td>Get</td></tr><tr><td>PostUserInfos</td><td>Get, List</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Go 1.21 or newer</li><li>OAuth2 credentials (optional for read-only access with API key)</li></ul>`,11)])])}const g=t(o,[["render",n]]);export{h as __pageData,g as default};
